import sys,difflib,re
L=open(sys.argv[1],encoding='utf-8').read().split('\n')
minus=[];plus=[]
def flush():
    global minus,plus
    n=max(len(minus),len(plus))
    for i in range(n):
        a=minus[i] if i<len(minus) else ''
        b=plus[i] if i<len(plus) else ''
        ta=re.findall(r'\s+|\w+|[^\w\s]',a);tb=re.findall(r'\s+|\w+|[^\w\s]',b)
        sm=difflib.SequenceMatcher(None,ta,tb,autojunk=False)
        out=[]
        for op,i1,i2,j1,j2 in sm.get_opcodes():
            if op=='equal':
                s=''.join(ta[i1:i2])
                out.append(s if len(s)<80 else s[:35]+' ... '+s[-35:])
            else:
                if i2>i1: out.append('[-'+''.join(ta[i1:i2])+'-]')
                if j2>j1: out.append('{+'+''.join(tb[j1:j2])+'+}')
        print('@@ pair',i);print(''.join(out));print()
    minus=[];plus=[]
for l in L:
    if l.startswith('---') or l.startswith('+++') or l.startswith('diff') or l.startswith('index'): continue
    if l.startswith('-'): minus.append(l[1:])
    elif l.startswith('+'): plus.append(l[1:])
    else:
        flush()
        if l.startswith('@@'): print('=====',l[:60])
flush()
EOF
python -I $S/wd.py $S/bdy.diff > $S/bdy.wd; wc -c $S/bdy.wd; head -c 30000 $S/bdy.wd

